class Solution:
    def decodeString(self, s: str) -> str:
        stk = []

        for i in range(len(s)):

            if s[i] != ']':
                stk.append(s[i])  
            else:
                strr = ''
                while stk[-1] != '[':
                    strr = stk.pop() + strr
                stk.pop()

                num = ''
                while stk and stk[-1].isdigit():
                    num = stk.pop() + num

                stk.append(int(num) * strr)

        return ''.join(stk)

class Solution:
    def decodeString(self, s: str) -> str:
        n, curr, nums, strs = 0, [], [], []
        for c in s:
            if c.isdigit():
                n = n*10 + ord(c)-ord('0')
            elif c.isalpha():
                curr.append(c)
            elif c == '[':
                nums.append(n)
                strs.append(curr)
                n, curr = 0, []
            elif c == ']':
                strs[-1].extend(curr*nums.pop())
                curr = strs.pop()
        return "".join(curr)

