class Solution:
    def removeKdigits(self, s: str, k: int) -> str:
        if len(s) == k:
            return '0'
        stack = []
        delete = {}
        for i in range(len(s)):

            while stack and s[i] < stack[-1][0]:
                delete[stack.pop()[1]] = 1
                if len(delete) == k:
                    break
            if len(delete) == k:
                return self.deleteindexes(s, delete, k)
            stack.append([s[i], i])
        s1 = self.deleteindexes(s, delete, k)

        return str(int(s1[:len(s1)-k +len(delete)]))


    def deleteindexes(self, s, delete, k):
        if not delete:
            return s
        if len(delete) == k:
            return str(int(''.join([c for ind, c in enumerate(s) if ind not in delete])))
        else:
            return ''.join([c for ind, c in enumerate(s) if ind not in delete])

class Solution:
    def removeKdigits(self, num, k):
        result = []
        for d in num:
            while k and result and result[-1] > d:
                result.pop()
                k -= 1
            result.append(d)
        return ''.join(result).lstrip('0')[:-k or None] or '0'

class Solution:
    def canCross(self, stones):
        if stones[1] != 1:
            return False

        last_jump_units = {s: set() for s in stones}
        last_jump_units[1].add(1)
        for s in stones[:-1]:
            for j in last_jump_units[s]:
                for k in (j-1, j, j+1):
                    if k > 0 and s+k in last_jump_units:
                        last_jump_units[s+k].add(k)
        return bool(last_jump_units[stones[-1]])

class Solution:
    def toHex(self, num: int) -> str:
        if not num:
            return "0"

        result = []
        while num and len(result) != 8:
            h = num & 15
            if h < 10:
                result.append(str(chr(ord('0') + h)))
            else:
                result.append(str(chr(ord('a') + h-10)))
            num >>= 4
        result.reverse()

        return "".join(result)

